"use strict";(globalThis.webpackChunkvegasat=globalThis.webpackChunkvegasat||[]).push([[8130],{7735(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"scorpius-5","metadata":{"permalink":"/blog/scorpius-5","editUrl":"https://github.com/VegaSat/website/blog/2026-03-24-Scorpius-update-5.md","source":"@site/blog/2026-03-24-Scorpius-update-5.md","title":"Coming soon","description":"TBD","date":"2026-03-24T00:00:00.000Z","tags":[{"inline":false,"label":"Scorpius 2025","permalink":"/blog/tags/scorpius-2025","description":"Scorpius 2025"}],"readingTime":0.01,"hasTruncateMarker":true,"authors":[{"name":"Luka Kljun","page":{"permalink":"/blog/authors/luka-kljun"},"key":"luka-kljun"}],"frontMatter":{"slug":"scorpius-5","title":"Coming soon","authors":["luka-kljun"],"tags":["2025-scorpius"]},"unlisted":false,"nextItem":{"title":"Kako delamo na CanSatu - ScorpiusSat","permalink":"/blog/scorpius-2"}},"content":"TBD\\n\\n{/* truncate */}"},{"id":"scorpius-2","metadata":{"permalink":"/blog/scorpius-2","editUrl":"https://github.com/VegaSat/website/blog/2026-03-13-Scorpius-update-2.md","source":"@site/blog/2026-03-13-Scorpius-update-2.md","title":"Kako delamo na CanSatu - ScorpiusSat","description":"Na\u0161e delo temelji na kombinaciji mehanskega in elektronskega razvoja. Ohi\u0161je je iz steklenih vlaken, notranjost pa je na 3D tiskanih ABS nosilcih. Elektronski sistem z ESP32 zbira podatke senzorjev in krmili servo motor padala, telemetrija pa poteka prek Digi XBee modula 868 MHz. Programska oprema uporablja modularni ve\u010dnitni pristop z varnostnimi mehanizmi.","date":"2026-03-13T00:00:00.000Z","tags":[{"inline":false,"label":"Scorpius 2025","permalink":"/blog/tags/scorpius-2025","description":"Scorpius 2025"}],"readingTime":0.27,"hasTruncateMarker":true,"authors":[{"name":"Luka Kljun","page":{"permalink":"/blog/authors/luka-kljun"},"key":"luka-kljun"}],"frontMatter":{"slug":"scorpius-2","title":"Kako delamo na CanSatu - ScorpiusSat","authors":["luka-kljun"],"tags":["2025-scorpius"]},"unlisted":false,"prevItem":{"title":"Coming soon","permalink":"/blog/scorpius-5"},"nextItem":{"title":"Prvi testni polet - BeeSat","permalink":"/blog/beesat-prvi-testni-polet"}},"content":"Na\u0161e delo temelji na kombinaciji mehanskega in elektronskega razvoja. Ohi\u0161je je iz steklenih vlaken, notranjost pa je na 3D tiskanih ABS nosilcih. Elektronski sistem z ESP32 zbira podatke senzorjev in krmili servo motor padala, telemetrija pa poteka prek Digi XBee modula 868 MHz. Programska oprema uporablja modularni ve\u010dnitni pristop z varnostnimi mehanizmi.\\n\\n{/* truncate */}"},{"id":"beesat-prvi-testni-polet","metadata":{"permalink":"/blog/beesat-prvi-testni-polet","editUrl":"https://github.com/VegaSat/website/blog/2026-03-06-BeeSat-update-3/index.md","source":"@site/blog/2026-03-06-BeeSat-update-3/index.md","title":"Prvi testni polet - BeeSat","description":"Z velikim ponosom lahko sporo\u010dimo, da smo uspe\u0161no izvedli prvi testni polet na\u0161ega CanSat-a!","date":"2026-03-06T00:00:00.000Z","tags":[{"inline":false,"label":"BeeSat 2025","permalink":"/blog/tags/beesat-2025","description":"BeeSat 2025"}],"readingTime":0.84,"hasTruncateMarker":true,"authors":[{"name":"Lin Cadez","page":{"permalink":"/blog/authors/lin-cadez"},"key":"lin-cadez"}],"frontMatter":{"title":"Prvi testni polet - BeeSat","slug":"beesat-prvi-testni-polet","authors":["lin-cadez"],"tags":["2025-beesat"],"image":"/img/beesat/new-fc.jpg"},"unlisted":false,"prevItem":{"title":"Kako delamo na CanSatu - ScorpiusSat","permalink":"/blog/scorpius-2"},"nextItem":{"title":"BeeSat 2.0 in izbolj\u0161ave zadnjih tednov","permalink":"/blog/beesat-v2-in-izboljsave"}},"content":"Z velikim ponosom lahko sporo\u010dimo, da smo uspe\u0161no izvedli **prvi testni polet na\u0161ega CanSat-a**!\\n\\n\x3c!-- truncate --\x3e\\n\\nTa test predstavlja enega klju\u010dnih mejnikov na\u0161ega projekta, saj smo z njim dokazali, da na\u0161a osnovna ideja deluje tudi v praksi.\\n\\n\ud83c\udfa5 Oglejte si kratek video testa, da vidite, kako leti na\u0161a \u010debel\'ca:\\n\\nhttps://youtube.com/shorts/ScsFvvAJW2I\\n\\n<hr></hr>\\n![](/img/beesat/new-fc.jpg)\\n\\n## Te\u017eave in izbolj\u0161ave\\nKot pri vsakem pravem testu, tudi tukaj ni \u0161lo vse popolnoma gladko \u2013 in prav to je del razvoja.\\n\\nMed testiranjem smo ugotovili, da:\\n- so se nam \u017eice **za\u010dele taliti zaradi obremenitve**,\\n- zato smo jih zamenjali z **\u017eicami, obdanimi s silikonom**, ki bolje prena\u0161ajo temperaturo in tokovne obremenitve.\\n\\nPoleg tega smo spremenili tudi nekaj nastavitev na flight controllerju (FC), kar bo dodatno izbolj\u0161alo stabilnost satelita med letenjem.\\n\\n## Kaj sledi?\\n\\nV naslednjih korakih se bomo osredoto\u010dili na:\\n- izbolj\u0161anje stabilizacije med letom,\\n- optimizacijo programske opreme,\\n- nadaljnje testne polete v realnih pogojih.\\n\\nTo je \u0161ele za\u010detek \u2013 najbolj zanimiv del \u0161e prihaja!\\n\\n\ud83d\udc49 Spremljajte nas tudi na Instagramu: [**@team.beesat**](https://www.instagram.com/team.beesat)"},{"id":"beesat-v2-in-izboljsave","metadata":{"permalink":"/blog/beesat-v2-in-izboljsave","editUrl":"https://github.com/VegaSat/website/blog/2026-03-03-BeeSat-update-2/index.md","source":"@site/blog/2026-03-03-BeeSat-update-2/index.md","title":"BeeSat 2.0 in izbolj\u0161ave zadnjih tednov","description":"V zadnjih tednih smo naredili velik korak naprej pri razvoju na\u0161ega CanSat-a.","date":"2026-03-03T00:00:00.000Z","tags":[{"inline":false,"label":"BeeSat 2025","permalink":"/blog/tags/beesat-2025","description":"BeeSat 2025"}],"readingTime":0.74,"hasTruncateMarker":true,"authors":[{"name":"Lin Cadez","page":{"permalink":"/blog/authors/lin-cadez"},"key":"lin-cadez"}],"frontMatter":{"title":"BeeSat 2.0 in izbolj\u0161ave zadnjih tednov","slug":"beesat-v2-in-izboljsave","authors":["lin-cadez"],"tags":["2025-beesat"],"image":"/img/beesat/cansat-development-beeslika.png"},"unlisted":false,"prevItem":{"title":"Prvi testni polet - BeeSat","permalink":"/blog/beesat-prvi-testni-polet"},"nextItem":{"title":"Naro\u010dilo PCB in izdelava elektronike","permalink":"/blog/scorpius-4"}},"content":"V zadnjih tednih smo naredili velik korak naprej pri razvoju na\u0161ega CanSat-a.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Nova verzija vezja (v2)\\n\\nIzdelali smo **novo verzijo PCB-ja**, kjer smo:\\n\\n* integrirali vezje z **beeperjem** (prej lo\u010deno),\\n* zmanj\u0161ali celotno velikost vezja,\\n* odstranili nepotrebne komponente (npr. reset gumb, statusne ledice).\\n\\nS tem smo optimizirali prostor in zmanj\u0161ali kompleksnost sistema, s \u010dimer smo kon\u010dno pri\u0161li v okvir maksimalnih prostorskih omejitev tekmovanja.\\n\\n<img src=\\"/img/beesat/cansat-development-beeslika.png\\"></img>\\n\\n## Izbolj\u0161an mehanski dizajn\\n\\nNekoliko smo prenovili tudi mehanizem letenja:\\n\\n* poglobili smo sistem za odpiranje ro\u010dic,\\n* zdaj se **ro\u010dice s propelerji v celoti pospravijo v notranjost satelita**,\\n* zmanj\u0161ali smo zunanje mere, da ustrezamo tekmovalnim zahtevam (66 mm premer).\\n\\n\\nNa\u0161a sekundarna misija o pristanku satelita brez padala je vedno bli\u017eje temu, da postane resni\u010dnost!!!\\n\\n\\n\\n## Kaj sledi?\\n\\nV prihodnjih tednih bomo izvedli prvi testni polet in se posvetili programiranju zemeljske bazne postaje\\n\\n\ud83d\udc49 Spremljajte na\u0161 napredek tudi na Instagramu! team.beesat"},{"id":"scorpius-4","metadata":{"permalink":"/blog/scorpius-4","editUrl":"https://github.com/VegaSat/website/blog/2026-02-13-Scorpius-update-4.md","source":"@site/blog/2026-02-13-Scorpius-update-4.md","title":"Naro\u010dilo PCB in izdelava elektronike","description":"Za CanSat smo razvili lasten PCB, ki povezuje senzorje, generator in telemetrijski modul. Izbrali smo FR-4 laminat, predvideli pa tudi mo\u017enost fleksibilnih PCB-jev. Sistem vklju\u010duje stabilizacijo napetosti, za\u0161\u010dito pred previsoko napetostjo iz sekundarne misije ter merjenje toka in napetosti za spremljanje proizvodnje energije. Po naro\u010dilu PCB smo izvedli integracijske teste povezav in kompatibilnosti.","date":"2026-02-13T00:00:00.000Z","tags":[{"inline":false,"label":"Scorpius 2025","permalink":"/blog/tags/scorpius-2025","description":"Scorpius 2025"}],"readingTime":0.28,"hasTruncateMarker":true,"authors":[{"name":"Luka Kljun","page":{"permalink":"/blog/authors/luka-kljun"},"key":"luka-kljun"}],"frontMatter":{"slug":"scorpius-4","title":"Naro\u010dilo PCB in izdelava elektronike","authors":["luka-kljun"],"tags":["2025-scorpius"]},"unlisted":false,"prevItem":{"title":"BeeSat 2.0 in izbolj\u0161ave zadnjih tednov","permalink":"/blog/beesat-v2-in-izboljsave"},"nextItem":{"title":"Na\u0161 CanSat po\u010dasi nastaja - BeeSat","permalink":"/blog/nas-cansat-pocasi-nastaja"}},"content":"Za CanSat smo razvili lasten PCB, ki povezuje senzorje, generator in telemetrijski modul. Izbrali smo FR-4 laminat, predvideli pa tudi mo\u017enost fleksibilnih PCB-jev. Sistem vklju\u010duje stabilizacijo napetosti, za\u0161\u010dito pred previsoko napetostjo iz sekundarne misije ter merjenje toka in napetosti za spremljanje proizvodnje energije. Po naro\u010dilu PCB smo izvedli integracijske teste povezav in kompatibilnosti.\\n\\n{/* truncate */}"},{"id":"nas-cansat-pocasi-nastaja","metadata":{"permalink":"/blog/nas-cansat-pocasi-nastaja","editUrl":"https://github.com/VegaSat/website/blog/2026-01-16-BeeSat-update-1/index.md","source":"@site/blog/2026-01-16-BeeSat-update-1/index.md","title":"Na\u0161 CanSat po\u010dasi nastaja - BeeSat","description":"Na\u0161 CanSat je zasnovan kot modularna enota, ki omogo\u010da zbiranje atmosferskih","date":"2026-01-16T00:00:00.000Z","tags":[{"inline":false,"label":"BeeSat 2025","permalink":"/blog/tags/beesat-2025","description":"BeeSat 2025"}],"readingTime":1.15,"hasTruncateMarker":true,"authors":[{"name":"Lin Cadez","page":{"permalink":"/blog/authors/lin-cadez"},"key":"lin-cadez"},{"name":"Jure Gr\u010dar","page":{"permalink":"/blog/authors/jure-grcar"},"key":"jure-grcar"}],"frontMatter":{"title":"Na\u0161 CanSat po\u010dasi nastaja - BeeSat","slug":"nas-cansat-pocasi-nastaja","authors":["lin-cadez","jure-grcar"],"tags":["2025-beesat"],"image":"/img/beesat/cansat-development2.png"},"unlisted":false,"prevItem":{"title":"Naro\u010dilo PCB in izdelava elektronike","permalink":"/blog/scorpius-4"},"nextItem":{"title":"Sekundarna misija \u2013 regenerativni vetrni generator - ScorpiusSat","permalink":"/blog/scorpius-3"}},"content":"Na\u0161 CanSat je zasnovan kot modularna enota, ki omogo\u010da zbiranje atmosferskih\\npodatkov in izvedbo avtonomnega pristanka. Ve\u010dina strukture je izdelana s\\n3D-tiskanjem, saj ta na\u010din izdelave omogo\u010da enostavno proizvodnjo, nizko maso in\\nhitro izdelavo novih prototipov.\\n<hr></hr>\\n\\n\x3c!-- truncate --\x3e\\n<div class=\\"sideBySide\\">\\n<img src=\\"/img/beesat/3dmodel.png\\"></img>\\n\\n# Sestava CanSata\\nNa\u0161 CanSat je v osnovi samo zlo\u017eljiv FPV dron. \u010ce bi \u017eeleli bi ga lahko upravljali celo z daljincem za drone.\\nCanSat je sestavljen iz treh lo\u010denih delov. V spodnjem delu so name\u0161\u010dene elektronske\\nkomponente. V srednjem delu je prostor, skozi katerega te\u010dejo vse \u017eice in kamor se med vzponom zlo\u017eijo ro\u010dice drona, ki dr\u017eijo motor\u010dke. V zadnjem, zgornjem delu se nahaja ta GPS modul in servo motor, ki aktivira spustitev ro\u010dic.\\n</div>\\n\\n# Razporeditev komponent\\nKomponente so razporejene vertikalno znotraj strukture. Kot \u017ee prej omenjeno - v zgornjem delu je name\u0161\u010den\\nservo mehanizem za postavitev ro\u010dic drona v polo\u017eaj letenja. Pod njim se nahajata flight controller (FC) in electronic speed controller (ESC), ki sta odgovorna za delovanje in napajanje motor\u010dkov. \u010cisto na dnu se nahaja baterija, pod njo pa \u0161e na\u0161 PCB, ki je bil izdelan po meri in RF modulom.\\n\\n# Dimenzije in materiali\\nOhi\u0161je je cilindri\u010dne oblike s premerom 66 mm in vi\u0161ino 115mm, kar je skladno z omejitvami\\ntekmovanja. CanSat je sestavljen iz treh delov, natisnjenih iz PLA plastike, ki so med seboj povezanih s kovinskimi vijaki."},{"id":"scorpius-3","metadata":{"permalink":"/blog/scorpius-3","editUrl":"https://github.com/VegaSat/website/blog/2026-01-13-Scorpius-update-3.md","source":"@site/blog/2026-01-13-Scorpius-update-3.md","title":"Sekundarna misija \u2013 regenerativni vetrni generator - ScorpiusSat","description":"Sekundarna misija preizku\u0161a pridobivanje elektri\u010dne energije med spustom. Na spodnji del satelita smo namestili OT3569 vetrni generator, ki kineti\u010dno energijo zraka pretvarja v elektri\u010dno. Merimo odvisnost mo\u010di od hitrosti vrtenja in gostote zraka, hkrati pa vpliv oblike padala in konfiguracije propelerja na stabilnost in izkoristek. Do zdaj smo izmerili do 8 V napetosti.","date":"2026-01-13T00:00:00.000Z","tags":[{"inline":false,"label":"Scorpius 2025","permalink":"/blog/tags/scorpius-2025","description":"Scorpius 2025"}],"readingTime":0.27,"hasTruncateMarker":true,"authors":[{"name":"Luka Kljun","page":{"permalink":"/blog/authors/luka-kljun"},"key":"luka-kljun"}],"frontMatter":{"slug":"scorpius-3","title":"Sekundarna misija \u2013 regenerativni vetrni generator - ScorpiusSat","authors":["luka-kljun"],"tags":["2025-scorpius"]},"unlisted":false,"prevItem":{"title":"Na\u0161 CanSat po\u010dasi nastaja - BeeSat","permalink":"/blog/nas-cansat-pocasi-nastaja"},"nextItem":{"title":"Za\u010detek projekta ScorpiusSat","permalink":"/blog/scorpius-1"}},"content":"Sekundarna misija preizku\u0161a pridobivanje elektri\u010dne energije med spustom. Na spodnji del satelita smo namestili OT3569 vetrni generator, ki kineti\u010dno energijo zraka pretvarja v elektri\u010dno. Merimo odvisnost mo\u010di od hitrosti vrtenja in gostote zraka, hkrati pa vpliv oblike padala in konfiguracije propelerja na stabilnost in izkoristek. Do zdaj smo izmerili do 8 V napetosti.\\n\\n{/* truncate */}"},{"id":"scorpius-1","metadata":{"permalink":"/blog/scorpius-1","editUrl":"https://github.com/VegaSat/website/blog/2025-11-13-Scorpius-update-1.md","source":"@site/blog/2025-11-13-Scorpius-update-1.md","title":"Za\u010detek projekta ScorpiusSat","description":"V leto\u0161njem letu smo se kot ekipa ScorpiusSat lotili izziva CanSat tekmovanja. Na\u0161 glavni cilj je bil razviti majhen satelit, ki med spu\u0161\u010danjem z vi\u0161ine meri atmosferske parametre in preizkusi sekundarno misijo regenerativnega pridobivanja elektri\u010dne energije. Vloge smo jasno razdelili, redna tedenska sre\u010danja in komunikacija prek Discorda pa so omogo\u010dili napredek po na\u010drtu.","date":"2025-11-13T00:00:00.000Z","tags":[{"inline":false,"label":"Scorpius 2025","permalink":"/blog/tags/scorpius-2025","description":"Scorpius 2025"}],"readingTime":0.27,"hasTruncateMarker":true,"authors":[{"name":"Luka Kljun","page":{"permalink":"/blog/authors/luka-kljun"},"key":"luka-kljun"}],"frontMatter":{"slug":"scorpius-1","title":"Za\u010detek projekta ScorpiusSat","authors":["luka-kljun"],"tags":["2025-scorpius"]},"unlisted":false,"prevItem":{"title":"Sekundarna misija \u2013 regenerativni vetrni generator - ScorpiusSat","permalink":"/blog/scorpius-3"},"nextItem":{"title":"Testing our cansat","permalink":"/blog/testing-our-cansat"}},"content":"V leto\u0161njem letu smo se kot ekipa ScorpiusSat lotili izziva CanSat tekmovanja. Na\u0161 glavni cilj je bil razviti majhen satelit, ki med spu\u0161\u010danjem z vi\u0161ine meri atmosferske parametre in preizkusi sekundarno misijo regenerativnega pridobivanja elektri\u010dne energije. Vloge smo jasno razdelili, redna tedenska sre\u010danja in komunikacija prek Discorda pa so omogo\u010dili napredek po na\u010drtu.\\n\\n{/* truncate */}"},{"id":"testing-our-cansat","metadata":{"permalink":"/blog/testing-our-cansat","editUrl":"https://github.com/VegaSat/website/blog/2023-06-22-Testing-our-cansat/index.md","source":"@site/blog/2023-06-22-Testing-our-cansat/index.md","title":"Testing our cansat","description":"On Tuesday, 20. 6. our team visited the Aerodium vertical wind tunnel in Logatec, who have kindly allowed us to test our CanSat in their facility. Our parachute performed exceptionally well, but unfortunately, we ran into some issues with the battery so we couldn\u2019t test our motors.","date":"2023-06-22T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":2.42,"hasTruncateMarker":true,"authors":[{"name":"Lovro Govekar","page":{"permalink":"/blog/authors/lovro-govekar"},"key":"lovro-govekar"}],"frontMatter":{"slug":"testing-our-cansat","title":"Testing our cansat","authors":["lovro-govekar"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"Za\u010detek projekta ScorpiusSat","permalink":"/blog/scorpius-1"},"nextItem":{"title":"Reports","permalink":"/blog/reports"}},"content":"On Tuesday, 20. 6. our team visited the Aerodium vertical wind tunnel in Logatec, who have kindly allowed us to test our CanSat in their facility. Our parachute performed exceptionally well, but unfortunately, we ran into some issues with the battery so we couldn\u2019t test our motors.\\n\\n{/* truncate */}\\n![Team member holding cansat in wind tunnel](IMG_2114.jpg)\\n![Team picture 1](IMG_2129.jpg)\\n![Team picture 1](IMG_2137.jpg)\\n\\nThe next day, we went on a trip to a military air base near Cerklje ob Krki, intending to test our locator and guidance systems, as well as the primary mission hardware and software. The test started off quite badly, as the L293D IC controlling our motors died and we had no spares, so we had no guidance.\\n![Military officer helipg us fix our cansat](IMG_2143.jpg)\\n\\nWith that in mind, we set off to ascend to a kilometer aboard a Bell 206 helicopter of the Slovenian army. With help from two very kind soldiers, we successfully dropped the CanSat. Due to its small size, we were, unfortunately, unable to watch it descend.\\n![Team member standing with our cansat v1 the last time we saw it](IMG_2154.jpg)\\n\\nHere is where the real trouble began. Due to a malfunction in the ground station antenna, we received no data from the CanSat during its flight. But OK, it\'s a missed opportunity for a proper test, or so we thought. The bad news didn\'t end there. As we set off to recover our CanSat, we quickly realized the transmitter onboard had stopped transmitting. We had no way to find our CanSat using radios, and after three hours of sweeping the airfield, we gave up. We concluded that the antenna on the APC220 transmitter must have broken off during the harsh landing.\\n![A person driving a car on inactive runway looking for our cansat in the surrounding fields](20230621_151904.jpg)\\n\\nWe are now left without a CanSat, four days before we leave for Spain. But we will make it, we always have. This experience taught us many important lessons, which we are taking into consideration as we build CanSat #2. Our design has changed. Instead of four horizontal PCBs, which needed to be inter-connected, introducing multiple points of failure, we designed two vertical PCBs, independent of each other, thus reducing many points where our CanSat could fail. Besides getting rid of janky connections between PCBs, we also repositioned our antenna so that it takes up less space and can be additionally braced and reinforced. We also put the buzzer on a separate PCB, with its own battery. The motors now also have a switch to turn them off during testing.\\n![Messy workspace after rebuilding cansat in a day](20230622_131249.jpg)\\n\\nDespite our bad luck yesterday, we\'d like to thank both Aerodium Logatec and the Slovenian army for helping us with our tests and teaching us many important lessons."},{"id":"reports","metadata":{"permalink":"/blog/reports","editUrl":"https://github.com/VegaSat/website/blog/2023-06-11-Reports/index.md","source":"@site/blog/2023-06-11-Reports/index.md","title":"Reports","description":"This post contains the 2 main documents we needed to submit to the ESA before the launch campaign. Critical Design Review (CDR) was submitted on 30th March and contains our idea of guided landing described in detail and the Pre Launch Report (PLR) that was submitted on 9th June and contains a description of every aspect of CanSat\'s operations.","date":"2023-06-11T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":0.35,"hasTruncateMarker":true,"authors":[{"name":"Jaka Kovac","page":{"permalink":"/blog/authors/jaka-kovac"},"key":"jaka-kovac"},{"name":"Lovro Govekar","page":{"permalink":"/blog/authors/lovro-govekar"},"key":"lovro-govekar"},{"name":"Luka Petek","page":{"permalink":"/blog/authors/luka-petek"},"key":"luka-petek"}],"frontMatter":{"slug":"reports","title":"Reports","authors":["jaka-kovac","lovro-govekar","luka-petek"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"Testing our cansat","permalink":"/blog/testing-our-cansat"},"nextItem":{"title":"Making of the guidance transmitter","permalink":"/blog/making-of-the-guidance-transmitter"}},"content":"This post contains the 2 main documents we needed to submit to the ESA before the launch campaign. Critical Design Review (CDR) was submitted on 30th March and contains our idea of guided landing described in detail and the Pre Launch Report (PLR) that was submitted on 9th June and contains a description of every aspect of CanSat\'s operations. \\n\\n{/* truncate */}\\n\\n[Critical design review](CDR2023.pdf)\\n\\n[Pre launch report](PLR2023.pdf)"},{"id":"making-of-the-guidance-transmitter","metadata":{"permalink":"/blog/making-of-the-guidance-transmitter","editUrl":"https://github.com/VegaSat/website/blog/2023-05-14-Making-of-the-guidance-transmitter/index.md","source":"@site/blog/2023-05-14-Making-of-the-guidance-transmitter/index.md","title":"Making of the guidance transmitter","description":"Today we\'ll write about how we made on-ground transmitters for the direction of our CanSat to the target landing location.","date":"2023-05-14T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":2.62,"hasTruncateMarker":true,"authors":[{"name":"Jaka Kovac","page":{"permalink":"/blog/authors/jaka-kovac"},"key":"jaka-kovac"}],"frontMatter":{"slug":"making-of-the-guidance-transmitter","title":"Making of the guidance transmitter","authors":["jaka-kovac"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"Reports","permalink":"/blog/reports"},"nextItem":{"title":"The past month","permalink":"/blog/the-past-month"}},"content":"Today we\'ll write about how we made on-ground transmitters for the direction of our CanSat to the target landing location.\\n\\n{/*truncate */}\\n\\nTo begin with, let\'s explain our system in more detail. We will position 3 transmitters to known locations in advance of the takeoff. Because they all will transmit FM signal on the same frequency only one will get correctly received. Assume that is the signal transmitted by the closest transmitter. We want to go towards the target, so we have to push our can away from the transmitter.\\n\\nSince all locations of the transmitters will be chosen in advance and will be programmed in the controller we calculate the azimuth of the trust. With the help of the onboard compass, we can determine what power each of the 3 guiding motors has to move at.\\n\\nWe devised our work into 3 parts.\\n\\n\\n\\n<details>\\n    <summary>Part 1 - Design internal circuitry for pulse generation</summary>\\n\\n    Once it was inevitable to use a transmitter, we immediately started planning our form of signal. We had 3 main ideas, either 3 distinct ASCII letters, 3 binary digits (like 1010 1010, 1100 1100, 1111 0000), or a square wave at 3 different frequencies. We decided on the latter because it\'s easy to generate even without a microcontroller (more on that note later) and has a hardware pulse counter. Hopefully, it won\'t hog the processor. The frequencies chosen were 600 Hz, 800 Hz and 1000 Hz; which is way less than a maximum of 40 MHz.\\n\\n    Since we want to have the ground transmitter done we still decided to use Arduino Nano as the signal source, but have plans to migrate to a 555-timer circuit if we end up with enough time.\\n\\n    To power everything we decided to use REV batteries with XT30 plug as we have multiple of them from another competition (https://firstglobal.si/). They output 12 V which means we can directly power the Arduino with it. With DIP switches you can select what frequency it transmits. We didn\'t yet know what we\'ll use for the radio transmitter, so we made our output signal line level (amplitude is 1 V) and we added a voltage divider to lower Arduino\'s 5 V to 1 V.\\n\\n    The circuit is accessible [here](circuit.png) and the code is [here](pcnt.h).\\n</details>\\n\\n\\n<details>\\n    <summary>Part 2 - Design antenna</summary>\\n\\n    2nd big part of the work was to design an antenna. First, we tried a dipole. It worked, tho range was an obvious problem. We decided to build something more directional. Yagi-Uda antennas are perfect for that. We build dual polarised Yagi-Uda antenna since then it\'s less important how it\'s directed.\\n\\n    We model our antenna in MMANA software since it\'s quite simple to use, has many tutorials online and for what we needed is free to use. The model can be found [here](antenna.png). The 3D emission diagram is found [here](emission.png). We will build it out of measuring tape, PVC pipe, hot glue and zip ties.\\n</details>\\n\\n<details>\\n    <summary>Part 3 - Choose the right transmitter</summary>\\n\\n    We chose SYN115 since that\'s what we already had on hand. \\n</details>"},{"id":"the-past-month","metadata":{"permalink":"/blog/the-past-month","editUrl":"https://github.com/VegaSat/website/blog/2023-04-22-The-past-month.md","source":"@site/blog/2023-04-22-The-past-month.md","title":"The past month","description":"Hello readers, it\'s been a while.","date":"2023-04-22T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":1.36,"hasTruncateMarker":true,"authors":[{"name":"Lovro Govekar","page":{"permalink":"/blog/authors/lovro-govekar"},"key":"lovro-govekar"}],"frontMatter":{"slug":"the-past-month","title":"The past month","authors":["lovro-govekar"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"Making of the guidance transmitter","permalink":"/blog/making-of-the-guidance-transmitter"},"nextItem":{"title":"Test of DTMF guidance system","permalink":"/blog/test-of-dtmf-guidance-system"}},"content":"Hello readers, it\'s been a while.\\n\\nWe thought you might want to know what we\'ve been up to during this time and, oh boy, we\'ve been busy.\\n\\n{/* truncate */}\\nDuring March, we were jump scared by the fast-approaching deadline for the Critical design report, which was at the end of said month. So we got to work. We chose and ordered most of the required parts, brainstormed designs for our guidance system, contacted some more possible sponsors, devised test plans, and wrote it all down. We got criticized by our mentors for most of the designs but in the end, it made the report even better. We look forward to hearing what ESA says about it on Wednesday though!\\n\\nBut that\'s not all we\'ve been up to. I\'ve mentioned already we\'ve been working on ways to test our work, and while most separate components can be tested in-house, the end product can not. On Thursday, April 20., we met with professor dr. Matev\u017e Dular from the Faculty of Mechanical Engineering in Ljubljana about trying out our guidance system in their wind tunnel. He was on board with the idea and also gave us some valuable insights that might improve our cansat. One of the most important ones might be using a streamer strip instead of a conventional parachute to make the cansat easier to guide and make the impact of possible winds lower, so that\'s another piece of the puzzle that we have to test.\\n\\nSo, we\'ve been busy, but there is still a lot of work to do, so we have to get back to it! See you later!"},{"id":"test-of-dtmf-guidance-system","metadata":{"permalink":"/blog/test-of-dtmf-guidance-system","editUrl":"https://github.com/VegaSat/website/blog/2023-03-15-Test-of-DTMF-guidance-system/index.md","source":"@site/blog/2023-03-15-Test-of-DTMF-guidance-system/index.md","title":"Test of DTMF guidance system","description":"At today\'s meeting, our team performed a test of the DTMF system that is the base of our guiding system.","date":"2023-03-15T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":2.12,"hasTruncateMarker":true,"authors":[{"name":"Jaka Kovac","page":{"permalink":"/blog/authors/jaka-kovac"},"key":"jaka-kovac"}],"frontMatter":{"slug":"test-of-dtmf-guidance-system","title":"Test of DTMF guidance system","authors":["jaka-kovac"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"The past month","permalink":"/blog/the-past-month"},"nextItem":{"title":"Our first meeting with ESA","permalink":"/blog/our-first-meeting-with-esa"}},"content":"At today\'s meeting, our team performed a test of the DTMF system that is the base of our guiding system.\\n\\n{/* truncate */}\\nDTMF or dual-tone multi-frequency signalling was used in old telephones. Even now some phones can beep differently based on what number you pressed. Every digit, characters * and # and letters A to D have 2 assigned frequencies arranged like in table 1.\\n\\n|        | 1209 Hz | 1336 Hz | 1477 Hz | 1633 Hz |\\n| ------ | ------- | ------- | ------- | ------- |\\n| 697 Hz | 1       | 2       | 3       | A       |\\n| 770 Hz | 4       | 5       | 6       | B       |\\n| 852 Hz | 7       | 8       | 9       | C       |\\n| 941 Hz | *       | 0       | #       | D       |\\nTable 1: DTMF frequencies combinations\\n\\nMost of our team members are now HAM radio operators and proud owners of our portable radios. Our mentor knew that those radios can transmit DTMF by pressing PTT (Push To Talk) button and a number button.\\n\\nHow our guidance system works. Let\'s assume that we are using numbers 1, 4 and 7.\\n<details>\\n    <summary>How to choose the suitable numbers</summary>\\n\\n    The numbers you chose have to have one common frequency. Therefore they have to be either in the same row or column. \\n</details>\\n\\nIf we arrange those 3 transmitters in an equilateral triangle we can guide the receiver station to the middle of the triangle. To understand how that would work one first needs to understand the addition of sine waves.\\n\\nIf you have multiple signals made of sine waves of multiple frequencies you can add all sinuses with the same frequency first and then add sums to get the sum of all signals. Sum of 2 sine waves with same frequency will have the lowest amplitude if amplitude of both of them is equal (it will be 0 if signals are 180\xb0 out of phase).\\n\\n![Graph](graph.gif)\\n\\n<details>\\n    <summary>Graph exlanation</summary>\\n\\n    Although the graph shows 2 waves it works similarly with 3.\\n    - The light blue line shows the output signal of station 1\\n    - The light green line shows the output signal of station 2\\n    - The blue line shows the received signal from station 1\\n    - The green line shows the received signal from station 2\\n    - The purple line shows the sum of received signals\\n    For 3 stations just imagine one graph like this for every pair.\\n</details>\\n\\nThe amplitude of the sum can be used to find the distance from centerpoint of transmitting stations to the receiver. If we have 3 of those differences, we can try to minimise all of them and when the amplitude if all received sine waves is smallest we know we hit the center of the triangle."},{"id":"our-first-meeting-with-esa","metadata":{"permalink":"/blog/our-first-meeting-with-esa","editUrl":"https://github.com/VegaSat/website/blog/2023-01-12-Our-first-meeting-with-ESA.md","source":"@site/blog/2023-01-12-Our-first-meeting-with-ESA.md","title":"Our first meeting with ESA","description":"Yesterday, 11.1.2023, we met with members of the commission from the European Space Agency and the Slovakian team, which is enrolling in the CanSat competition for the first time this year. We presented our secondary mission to the commission and admired the very interesting goals the Slovakian team have set themselves.","date":"2023-01-12T00:00:00.000Z","tags":[{"inline":false,"label":"VegaSat 2023","permalink":"/blog/tags/2023","description":"VegaSat 2023"}],"readingTime":0.81,"hasTruncateMarker":true,"authors":[{"name":"Lovro Govekar","page":{"permalink":"/blog/authors/lovro-govekar"},"key":"lovro-govekar"}],"frontMatter":{"slug":"our-first-meeting-with-esa","title":"Our first meeting with ESA","authors":["lovro-govekar"],"tags":["2023"]},"unlisted":false,"prevItem":{"title":"Test of DTMF guidance system","permalink":"/blog/test-of-dtmf-guidance-system"}},"content":"Yesterday, 11.1.2023, we met with members of the commission from the European Space Agency and the Slovakian team, which is enrolling in the CanSat competition for the first time this year. We presented our secondary mission to the commission and admired the very interesting goals the Slovakian team have set themselves.\\n\\n{/* truncate */}\\n\\nWe, however, have also set ourselves quite a goal, commented on by ESA\u2019s commission as \u201crarely successful\u201d. Our mission is split into multiple parts, the first and main of which is to attempt a directed landing. During the mission, we will be collecting loads of data about our cansat\u2019s speed, attitude, altitude and location, as well as the data we are collecting as part of our primary mission. Using this data, we will create an animation of the flight in Blender. We are also planning to build self-rotating antennas that track our cansat.\\n\\nAs for now, we\'re off to work on our mission.\\n\\nSee you in our next post!"}]}}')}}]);